    // --- LIFECYCLE ---
    protected override async Task OnInitializedAsync()
    {
        await LoadInitialData();
    }

    private async Task LoadInitialData()
    {
        try
        {
            maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel") ?? "02";
            selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "2025-2026";

            // Đọc học kỳ từ session (lưu bởi TopNavbar)
            var hocKyStr = await BrowserStorageService.GetItem(JS, "selectedHocKy");
            if (!string.IsNullOrEmpty(hocKyStr) && int.TryParse(hocKyStr, out var savedHocKy))
                selectedHocKy = savedHocKy.ToString();
            else
                selectedHocKy = (DateTime.Now.Month >= 8 && DateTime.Now.Month <= 12) ? "1" : "2";

            if (string.IsNullOrEmpty(maTruongBo))
            {
                await JS.InvokeVoidAsync("alert", "Không tìm thấy mã trường. Vui lòng đăng nhập lại.");
                Nav.NavigateTo("/");
                return;
            }

            await LoadData();
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
    }

    private async Task LoadData()
    {
        isLoading = true;
        StateHasChanged();

        try
        {
            originalData = await DiemService.hGetCauHinhLopMon(
                selectedCapHoc!,
                maTruongBo!,
                selectedNamHoc!,
                selectedHocKy
            );

            var lopHocs = await TruongService.hGetDanhSachLop(
                maTruongBo!,
                selectedCapHoc!,
                selectedNamHoc!
            );

            var khoiHocs = await TruongService.hGetDanhSachKhoi(
                maTruongBo!,
                selectedCapHoc!
            );

            BuildTreeStructure(originalData, lopHocs, khoiHocs);

            if (grades.Any() && grades.First().Classes.Any())
            {
                await SelectClass(grades.First().Classes.First(), grades.First());
            }
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    private void BuildTreeStructure(
        List<M_CauHinhLopMonDTO> configData,
        List<LopHoc_DTO> lopHocs,
        List<KhoiHoc_DTO> khoiHocs)
    {
        grades.Clear();

        var khoiGroups = khoiHocs.GroupJoin(
            lopHocs,
            k => k.MaKhoiBo,
            l => l.MaKhoiBo,
            (k, lopList) => new { Khoi = k, LopList = lopList.ToList() }
        );

        foreach (var khoiGroup in khoiGroups)
        {
            var grade = new GradeModel
            {
                MaKhoiBo = khoiGroup.Khoi.MaKhoiBo,
                Name = khoiGroup.Khoi.TenKhoi
            };

            foreach (var lop in khoiGroup.LopList)
            {
                var classModel = new ClassModel
                {
                    IdLopBo = lop.IdLopBo.ToString(),
                    MaKhoiBo = lop.MaKhoiBo,
                    Name = lop.TenLop,
                    TenLop = lop.TenLop,
                    GradeName = khoiGroup.Khoi.TenKhoi
                };

                var subjectsForClass = configData
                    .Where(x => x.IdLopBo == lop.IdLopBo)
                    .ToList();

                foreach (var subjectData in subjectsForClass)
                {
                    var subject = new SubjectModel
                    {
                        IdMonHocSo = subjectData.IdMonHocSo,
                        Name = subjectData.TenMonHoc,
                        IsChecked = subjectData.IsHienThi == 1,
                        OriginalChecked = subjectData.IsHienThi == 1,
                        MaHocKy = subjectData.MaHocKy ?? ""
                    };
                    classModel.Subjects.Add(subject);
                }

                grade.Classes.Add(classModel);
            }

            grades.Add(grade);
        }
    }

    private async Task SelectClass(ClassModel cls, GradeModel grade)
    {
        selectedClass = cls;
        await LoadSubjectsForClass(cls.IdLopBo, grade.MaKhoiBo);
        StateHasChanged();
    }

    private async Task LoadSubjectsForClass(string idLopBo, string maKhoiBo)
    {
        if (string.IsNullOrEmpty(idLopBo) || originalData == null) return;

        isLoadingSubjects = true;
        StateHasChanged();

        try
        {
            subjects = originalData
                .Where(x => x.IdLopBo.ToString() == idLopBo)
                .Select(x => new SubjectModel
                {
                    IdMonHocSo = x.IdMonHocSo,
                    Name = x.TenMonHoc,
                    IsChecked = x.IsHienThi == 1,
                    OriginalChecked = x.IsHienThi == 1,
                    MaHocKy = x.MaHocKy ?? "",
                    LastUpdated = null
                })
                .ToList();

            CheckUnsavedChanges();
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isLoadingSubjects = false;
            StateHasChanged();
        }
    }

    private async Task ReloadSubjects()
    {
        if (selectedClass != null)
        {
            await LoadSubjectsForClass(selectedClass.IdLopBo, selectedClass.MaKhoiBo);
        }
    }

    // --- ACTIONS ---
    private void ToggleGrade(GradeModel grade)
    {
        grade.IsExpanded = !grade.IsExpanded;
        StateHasChanged();
    }

    private void ToggleSubject(SubjectModel subject)
    {
        subject.IsChecked = !subject.IsChecked;
        CheckUnsavedChanges();
        StateHasChanged();
    }

    private void ToggleAllSubjects(bool showAll)
    {
        bulkActionIsActive = showAll;
        showBulkConfirmModal = true;
        StateHasChanged();
    }

    private async Task ConfirmBulkToggle()
    {
        if (selectedClass != null)
        {
            foreach (var subject in subjects)
                subject.IsChecked = bulkActionIsActive;

            CheckUnsavedChanges();
            CloseBulkConfirmModal();
            StateHasChanged();

            await ShowToast(
                $"Đã {(bulkActionIsActive ? "hiển thị" : "ẩn")} tất cả {subjects.Count} môn học",
                bulkActionIsActive ? "success" : "warning");
        }
    }

    private async Task SaveAllChanges()
    {
        if (selectedClass == null || !hasUnsavedChanges) return;

        isSaving = true;
        StateHasChanged();

        try
        {
            var changedSubjects = subjects.Where(s => s.HasChanges).ToList();
            int savedCount = 0;
            int failedCount = 0;

            foreach (var subject in changedSubjects)
            {
                try
                {
                    var dto = new M_CauHinhLopMonDTO
                    {
                        MaTruongBo = maTruongBo!,
                        NamHoc = selectedNamHoc!,
                        IdLopBo = int.Parse(selectedClass.IdLopBo),
                        MaLopBo = selectedClass.Name,
                        TenLop = selectedClass.TenLop,
                        MaKhoiBo = selectedClass.MaKhoiBo,
                        TenKhoi = selectedClass.GradeName,
                        Cap = selectedCapHoc!,
                        IdMonHocSo = subject.IdMonHocSo,
                        TenMonHoc = subject.Name,
                        IsHienThi = subject.IsChecked ? 1 : 0,
                        MaHocKy = selectedHocKy
                    };

                    await DiemService.hUpsertCauHinhLopMon(dto);
                    subject.OriginalChecked = subject.IsChecked;
                    savedCount++;
                }
                catch (Exception ex)
                {
                    failedCount++;
                    Console.WriteLine($"Lỗi lưu môn {subject.Name}: {ex.Message}");
                }
            }

            CheckUnsavedChanges();

            if (failedCount > 0)
                await ShowToast($"Đã lưu {savedCount} môn, {failedCount} môn lỗi", "error");
            else
                await ShowToast($"Đã lưu thành công {savedCount} môn học", "success");
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isSaving = false;
            StateHasChanged();
        }
    }

    private void CancelChanges()
    {
        foreach (var subject in subjects)
            subject.IsChecked = subject.OriginalChecked;
        CheckUnsavedChanges();
        StateHasChanged();
    }

    private void CheckUnsavedChanges()
    {
        unsavedCount = subjects.Count(s => s.HasChanges);
        hasUnsavedChanges = unsavedCount > 0;

        if (selectedClass != null)
        {
            foreach (var subject in subjects)
            {
                var classSubject = selectedClass.Subjects.FirstOrDefault(s => s.IdMonHocSo == subject.IdMonHocSo);
                if (classSubject != null)
                    classSubject.IsChecked = subject.IsChecked;
            }
        }
    }

    private void CloseBulkConfirmModal()
    {
        showBulkConfirmModal = false;
        StateHasChanged();
    }

    // --- HELPER METHODS ---
    private string GetClassIconMaterial(int activeCount, int total)
    {
        if (total == 0) return "help_outline";
        if (activeCount == total) return "check_circle";
        if (activeCount == 0) return "cancel";
        return "rule";
    }

    private string GetOverallStatusClass()
    {
        if (subjects.Count == 0) return "neutral";
        int active = subjects.Count(s => s.IsChecked);
        if (active == subjects.Count) return "active";
        if (active == 0) return "inactive";
        return "partial";
    }

    private string GetOverallStatusText()
    {
        if (subjects.Count == 0) return "Chưa cấu hình";
        int active = subjects.Count(s => s.IsChecked);
        if (active == subjects.Count) return "Hiển thị tất cả";
        if (active == 0) return "Ẩn tất cả";
        return $"Một phần ({active}/{subjects.Count})";
    }

    // --- EVENT HANDLERS ---
    private async Task OnNamHocChanged(ChangeEventArgs e)
    {
        selectedNamHoc = e.Value?.ToString();
        await LoadData();
    }

    private async Task OnHocKyChanged(ChangeEventArgs e)
    {
        selectedHocKy = e.Value?.ToString() ?? "1";
        await LoadData();
    }

    #region func helper
    private async Task ShowToast(string message, string type = "info")
    {
        try
        {
            await JS.InvokeVoidAsync("showToast", message, type);
        }
        catch (JSException ex)
        {
            if (ex.Message.Contains("showToast"))
                await JS.InvokeVoidAsync("alert", $"{GetTypeEmoji(type)} {message}");
            else
                throw;
        }
    }

    private string GetTypeEmoji(string type) => type switch
    {
        "success" => "✅",
        "error" => "❌",
        "warning" => "⚠️",
        _ => "ℹ️"
    };
    #endregion

    // --- COPY CONFIG ---
    private void ShowCopyModal()
    {
        copyTargetClasses.Clear();
        copyMode = "class";
        copyOnlyVisible = false;
        showCopyModal = true;
        StateHasChanged();
    }

    private void CloseCopyModal()
    {
        showCopyModal = false;
        copyTargetClasses.Clear();
        StateHasChanged();
    }

    private void ToggleCopyTarget(string idLopBo)
    {
        if (copyTargetClasses.Contains(idLopBo))
            copyTargetClasses.Remove(idLopBo);
        else
            copyTargetClasses.Add(idLopBo);
        StateHasChanged();
    }

    private List<ClassModel> GetSameGradeClasses()
    {
        if (selectedClass == null) return new();
        return grades
            .FirstOrDefault(g => g.MaKhoiBo == selectedClass.MaKhoiBo)
            ?.Classes
            .Where(c => c.IdLopBo != selectedClass.IdLopBo)
            .ToList() ?? new();
    }

    private async Task ExecuteCopy()
    {
        if (selectedClass == null || subjects.Count == 0) return;

        List<string> targetIds;
        if (copyMode == "grade")
            targetIds = GetSameGradeClasses().Select(c => c.IdLopBo).ToList();
        else
            targetIds = copyTargetClasses.ToList();

        if (!targetIds.Any())
        {
            await ShowToast("Vui lòng chọn ít nhất một lớp đích.", "warning");
            return;
        }

        isCopying = true;
        StateHasChanged();

        int successCount = 0;
        int errorCount = 0;

        try
        {
            foreach (var targetId in targetIds)
            {
                ClassModel? targetClass = null;
                foreach (var g in grades)
                {
                    var c = g.Classes.FirstOrDefault(x => x.IdLopBo == targetId);
                    if (c != null) { targetClass = c; break; }
                }
                if (targetClass == null) continue;

                // Lấy môn hiện có của lớp đích
                var targetExistingIds = originalData?
                    .Where(x => x.IdLopBo.ToString() == targetId)
                    .Select(x => x.IdMonHocSo)
                    .ToHashSet() ?? new();

                foreach (var srcSubject in subjects)
                {
                    try
                    {
                        // Nếu chỉ copy trạng thái: bỏ qua môn chưa có ở lớp đích
                        if (copyOnlyVisible && !targetExistingIds.Contains(srcSubject.IdMonHocSo))
                            continue;

                        var dto = new M_CauHinhLopMonDTO
                        {
                            MaTruongBo = maTruongBo!,
                            NamHoc = selectedNamHoc!,
                            IdLopBo = int.Parse(targetId),
                            MaLopBo = targetClass.Name,
                            TenLop = targetClass.TenLop,
                            MaKhoiBo = targetClass.MaKhoiBo,
                            TenKhoi = targetClass.GradeName,
                            Cap = selectedCapHoc!,
                            IdMonHocSo = srcSubject.IdMonHocSo,
                            TenMonHoc = srcSubject.Name,
                            IsHienThi = srcSubject.IsChecked ? 1 : 0,
                            MaHocKy = selectedHocKy
                        };
                        await DiemService.hUpsertCauHinhLopMon(dto);
                    }
                    catch
                    {
                        errorCount++;
                    }
                }
                successCount++;
            }

            await LoadData();
            CloseCopyModal();

            if (errorCount == 0)
                await ShowToast($"Đã sao chép thành công vào {successCount} lớp!", "success");
            else
                await ShowToast($"Copy xong: {successCount} lớp, {errorCount} lỗi.", "warning");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error");
        }
        finally
        {
            isCopying = false;
            StateHasChanged();
        }
    }





